function populateOutput(data) {
  $('out-module-code').textContent = data.moduleCode || '';
  $('out-module-name').textContent = data.moduleName || '';

  const rawDesc = (data.moduleDescriptor || data.moduleDescription || '').trim();
  const normalizedDesc = rawDesc
    .split(/\n\s*\n/)
    .map(p => p.replace(/\r?\n+/g, ' ').replace(/\s{2,}/g, ' ').trim())
    .filter(Boolean)
    .join('\n\n');

  $('out-descriptor').textContent = normalizedDesc;

  // Populate Academic Cluster
  const clusterInfo = detectModuleAcademicCluster(data);
  const clusterSelect = $('out-academic-cluster');
  const clusterBadge = $('out-cluster-ai-badge');
  const clusterBadgeText = $('out-cluster-ai-badge-text');
  const clusterRationale = $('out-cluster-rationale');

  if (clusterSelect) clusterSelect.value = clusterInfo.code;
  if (clusterBadge) {
    clusterBadge.style.display = 'inline-flex';
    if (clusterBadgeText) {
      clusterBadgeText.textContent = (clusterInfo.source === 'ai') ? 'AI Identified' : 'Rule Detected';
    }
  }
  if (clusterRationale) {
    clusterRationale.textContent = clusterInfo.rationale || `Classified as ${clusterInfo.name} based on curriculum context.`;
  }

  populateSeparatedList('list-outcomes', data.learningOutcomes, 'card-outcomes', '4. Learning Outcomes');
  populateSeparatedList('list-topics', data.topicsCovered, 'card-topics', '5. Topics Covered & Details');
  populateSeparatedList('list-activities', data.learningActivities, 'card-activities', '6. Learning Activities & Details');

  // Reset previous AI recommendation cache so fresh AI recommendations generate when user proceeds
  window._geminiGeneratedForCurrentProfile = false;
  window._lastGeminiShortlist = null;
  window._lastGeminiProfileKey = null;
  window._lastEvaluatedRecTools = null;

  // Do not generate recommendations on the Step 1 / module profile page.
  // Recommendations are generated with Gemini 3.8 Flash only when user clicks "Proceed to Recommendation".

  // Keep collapsed initially as Picture 2 banner
  toggleOutputCollapse(true);
}

let isOutputPanelCollapsed = true;

function toggleOutputCollapse(forceState) {
  const body = $('output-collapsible-body');
  const arrow = $('output-banner-arrow');
  const banner = $('output-banner-header');

  if (typeof forceState === 'boolean') {
    isOutputPanelCollapsed = forceState;
  } else {
    isOutputPanelCollapsed = !isOutputPanelCollapsed;
  }

  if (body) {
    body.classList.toggle('collapsed', isOutputPanelCollapsed);
  }
  if (arrow) {
    arrow.textContent = isOutputPanelCollapsed ? '▼' : '▲';
  }
  if (banner) {
    banner.setAttribute('aria-expanded', (!isOutputPanelCollapsed).toString());
  }
}

function populateSeparatedList(listId, items, cardId, baseTitle) {
  const list = $(listId);
  if (!list) return;
  list.innerHTML = '';

  const cleanItems = splitIntoIndividualPoints(items);

  // Update card header count badge
  if (cardId && baseTitle) {
    const labelElem = document.querySelector(`#${cardId} .section-title-label`);
    if (labelElem) {
      labelElem.textContent = cleanItems.length > 0 ? `${baseTitle} (${cleanItems.length})` : baseTitle;
    }
  }

  if (cleanItems.length === 0) {
    addListItem(listId, '');
    return;
  }

  cleanItems.forEach(item => addListItem(listId, item));
}

function splitIntoIndividualPoints(rawItems) {
  const result = [];
  const items = Array.isArray(rawItems) ? rawItems : [rawItems];

  items.forEach(entry => {
    if (!entry) return;
    let text = '';
    if (typeof entry === 'string') {
      text = entry.trim();
    } else if (typeof entry === 'object') {
      if (entry.topic && entry.details) {
        text = `${entry.topic.trim()}: ${entry.details.trim()}`;
      } else if (entry.activity && entry.details) {
        text = `${stripStudyHours(entry.activity.trim())}: ${stripStudyHours(entry.details.trim())}`;
      } else if (entry.topic) {
        text = entry.topic.trim();
      } else if (entry.activity) {
        text = stripStudyHours(entry.activity.trim());
      } else if (entry.outcome) {
        text = entry.outcome.trim();
      } else {
        text = Object.values(entry).filter(Boolean).join(': ').trim();
      }
    } else {
      text = String(entry).trim();
    }

    if (!text) return;

    // If an item contains distinct double-newline paragraphs, preserve each paragraph as a point
    if (text.includes('\n\n')) {
      const paragraphs = text.split(/\n\s*\n/).map(p => p.replace(/\r?\n+/g, ' ').replace(/\s{2,}/g, ' ').trim()).filter(p => p.length > 0);
      paragraphs.forEach(p => {
        const cleanP = p.replace(/^[-•*►▶→]\s*/, '').replace(/^(?:LO|CLO)?\s*\d+[\.\:\-]\s*/i, '').trim();
        if (cleanP.length > 2) result.push(cleanP);
      });
      return;
    }

    // Join all soft line breaks into one single complete paragraph
    const completeParagraph = text
      .replace(/\r?\n+/g, ' ')
      .replace(/\s{2,}/g, ' ')
      .replace(/^[-•*►▶→]\s*/, '')
      .replace(/^(?:LO|CLO)?\s*\d+[\.\:\-]\s*/i, '')
      .trim();

    if (completeParagraph.length > 0) {
      result.push(completeParagraph);
    }
  });

  return result;
}




// ==========================================================================
// EVIDENCE-PRIORITIZED & NEEDS-BASED EDTECH TOOLS RECOMMENDATION ENGINE
// With Direct Google Gemini Pro Integration (.env Auto-Linked)
// Approach:
// Module Context → Learning Outcomes → Learning Activities → Assessment → Teaching Need → Suitable Tool
// ==========================================================================

let currentRecViewLimit = 5; // 5 (curated shortlist) or 'all'
let lastModuleDataForRecommendations = null;
let recDebounceTimer = null;
let autoGeminiApiKey = '';
let autoGeminiModel = 'gemini-3.8-flash';
let isGeminiGenerating = false;

// 1. Automatically link API key from .env without requiring user modal clicks
async function initServerEnvConfig() {
  try {
    const resp = await fetch('/api/config');
    if (resp.ok) {
      const data = await resp.json();
      if (data && data.geminiApiKey) {
        autoGeminiApiKey = data.geminiApiKey.trim();
        autoGeminiModel = data.geminiModel || 'gemini-3.8-flash';
        window._autoGeminiKey = autoGeminiApiKey;
        window._autoGeminiModel = autoGeminiModel;
        console.log(`[EdTechAId] Linked Google Gemini API key from .env (${autoGeminiModel})`);
        updateGeminiStatusBadge(true);
      } else {
        updateGeminiStatusBadge(false);
      }
    }
  } catch (e) {
    console.log('[EdTechAId] Local config check offline or standalone mode');
  }
}
initServerEnvConfig();

function updateGeminiStatusBadge(isLinked) {
  const badge = $('rec-gemini-status-badge');
  if (badge) {
    if (isLinked) {
      badge.innerHTML = `🟢 <strong>Gemini Pro Linked</strong> <span style="font-size:11px; opacity:0.85;">(.env)</span>`;
      badge.className = 'rec-principle-chip chip-highlight';
      badge.style.background = '#ecfdf5';
      badge.style.color = '#047857';
      badge.style.borderColor = '#6ee7b7';
    } else {
      badge.innerHTML = `🤖 <strong>Gemini Pro</strong> <span style="font-size:11px; opacity:0.85;">(Add key to .env)</span>`;
      badge.className = 'rec-principle-chip';
      badge.style.cursor = 'pointer';
      badge.title = 'Add your GEMINI_API_KEY into the .env file to activate AI generation.';
      badge.onclick = () => {
        showToast('💡 To link Gemini Pro, paste your GEMINI_API_KEY into the .env file and refresh!');
      };
    }
  }
  if (btnHeader) {
    if (isLinked) {
      btnHeader.classList.remove('hidden');
    }
  }
}

function setRecToolsViewLimit(limit) {
  const allEvaluated = (window._lastEvaluatedRecTools || []).slice();
  const maxTools = allEvaluated.length > 0 ? allEvaluated.length : 21;

  if (limit === 'all') {
    currentRecViewLimit = maxTools;
  } else if (typeof limit === 'number') {
    currentRecViewLimit = Math.max(5, Math.min(maxTools, limit));
  } else {
    currentRecViewLimit = 5;
  }

  const btnTop5 = $('btn-toggle-rec-top5');
  const btnAll = $('btn-toggle-rec-all');
  if (btnTop5) btnTop5.classList.toggle('active', currentRecViewLimit === 5);
  if (btnAll) btnAll.classList.toggle('active', currentRecViewLimit >= maxTools);

  if (window._lastEvaluatedRecTools && window._lastEvaluatedRecTools.length > 0) {
    renderPrincipledToolRecommendations(window._lastEvaluatedRecTools, window._lastEvaluatedClusterInfo);
  } else if (lastModuleDataForRecommendations) {
    generateAndRenderPrincipledRecommendations(lastModuleDataForRecommendations);
  }
}

function handleRecSeeMore() {
  const allEvaluated = (window._lastEvaluatedRecTools || []).slice();
  const maxTools = allEvaluated.length > 0 ? allEvaluated.length : 21;
  const currentCount = (typeof currentRecViewLimit === 'number') ? currentRecViewLimit : 5;
  const newLimit = Math.min(maxTools, currentCount + 2);
  setRecToolsViewLimit(newLimit);
}

function handleRecSeeLess() {
  const currentCount = (typeof currentRecViewLimit === 'number') ? currentRecViewLimit : 5;
  const newLimit = Math.max(5, currentCount - 2);
  setRecToolsViewLimit(newLimit);
}

function toggleShowMoreRecTools() {
  handleRecSeeMore();
}

function recalculateAndRenderToolRecommendations(forceAi = false, targetModel = null) {
  const comp = getModuleProfileComponents();
  generateAndRenderPrincipledRecommendations(comp, forceAi, targetModel);
  showToast('✨ Tool recommendations refreshed!');
}

function debouncedRecalculateRecommendations() {
  clearTimeout(recDebounceTimer);
  recDebounceTimer = setTimeout(() => {
    const comp = getModuleProfileComponents();
    if (comp.moduleCode || comp.moduleName || comp.moduleDescriptor || comp.learningOutcomes?.length) {
      generateAndRenderPrincipledRecommendations(comp, false);
    }
  }, 400);
}

// ─────────────────────────────────────────────────────────────
// Academic Cluster Detection & Profile Key Helper
// ─────────────────────────────────────────────────────────────
function getModuleProfileKey(comp) {
  if (!comp) return '';
  const code = (comp.moduleCode || $('out-module-code')?.textContent || '').trim().toUpperCase();
  const name = (comp.moduleName || $('out-module-name')?.textContent || '').trim().toLowerCase();
  const desc = (comp.moduleDescriptor || comp.moduleDescription || comp.descriptor || $('out-descriptor')?.textContent || '').trim().toLowerCase().slice(0, 80);
  const loList = (comp.learningOutcomes || (typeof getListItems === 'function' ? getListItems('list-outcomes') : []) || []);
  const loCount = loList.length;
  const clusterCode = (comp.academicCluster?.code || comp.cluster?.code || $('out-academic-cluster')?.value || 'ENG').toUpperCase();
  return `${code}|${name}|${desc}|${loCount}|${clusterCode}`;
}

const SIT_ACADEMIC_CLUSTERS = {
  ENG: { code: 'ENG', name: 'Engineering & Technology', icon: '⚙️' },
  ICT: { code: 'ICT', name: 'Infocomm Technology', icon: '💻' },
  BCD: { code: 'BCD', name: 'Business, Communication & Design', icon: '📊' },
  FCB: { code: 'FCB', name: 'Food, Chemical & Biotechnology', icon: '🧪' },
  HSS: { code: 'HSS', name: 'Health & Social Sciences', icon: '🏥' },
  OTHER: { code: 'OTHER', name: 'Other', icon: '🌐' }
};

async function detectAcademicClusterWithAI(comp) {
  const modCode = (comp.moduleCode || '').trim();
  const modName = (comp.moduleName || '').trim();
  const desc = (comp.moduleDescriptor || comp.moduleDescription || '').trim();
  const outcomes = (comp.learningOutcomes || []).map(o => (typeof o === 'string' ? o : o.text || '')).join('; ');
  const topics = (comp.topicsCovered || []).map(t => (typeof t === 'string' ? t : t.details ? `${t.topic}: ${t.details}` : t.topic || '')).join('; ');

  const prompt = `You are an academic curriculum classification expert for Singapore Institute of Technology (SIT).
Classify the following university module into EXACTLY ONE of SIT's 5 official Academic Clusters:
1. "ENG": Engineering & Technology (Mechanical, Electrical, Civil, Aerospace, Robotics, Systems Engineering, Marine, Mechatronics, CAD)
2. "ICT": Infocomm Technology (Software Engineering, Computer Science, Cybersecurity, Data Science, AI, Web/Mobile/Cloud Computing, Programming)
3. "BCD": Business, Communication & Design (Accountancy, Business Administration, Marketing, Finance, Digital Communications, UX/UI Design, Hospitality)
4. "FCB": Food, Chemical & Biotechnology (Chemical Engineering, Pharmaceutical Engineering, Food Science/Technology, Biotechnology, Applied Chemistry)
5. "HSS": Health & Social Sciences (Physiotherapy, Occupational Therapy, Diagnostic Radiography, Radiation Therapy, Nursing, Speech Therapy, Dietetics)

Module Code: ${modCode}
Module Title: ${modName}
Description: ${desc.slice(0, 1500)}
Learning Outcomes: ${outcomes.slice(0, 1000)}
Topics: ${topics.slice(0, 1000)}

Return strictly a valid JSON object matching this schema:
{
  "code": "ENG | ICT | BCD | FCB | HSS",
  "name": "Full cluster name",
  "rationale": "Brief 1-sentence reason based on syllabus content"
}`;

  try {
    const apiKey = autoGeminiApiKey || (typeof localStorage !== 'undefined' ? localStorage.getItem('edtech_user_api_key') : '') || '';
    const resp = await fetch('/api/gemini-generate', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        prompt,
        apiKey,
        model: autoGeminiModel || 'gemini-3.8-flash',
        maxTokens: 512,
        temperature: 0.1
      })
    });
    if (resp.ok) {
      const result = await resp.json();
      if (result.success && result.data && result.data.code) {
        const cleanCode = result.data.code.trim().toUpperCase();
        if (SIT_ACADEMIC_CLUSTERS[cleanCode]) {
          return {
            code: cleanCode,
            name: SIT_ACADEMIC_CLUSTERS[cleanCode].name,
            icon: SIT_ACADEMIC_CLUSTERS[cleanCode].icon,
            rationale: result.data.rationale || `Classified as ${SIT_ACADEMIC_CLUSTERS[cleanCode].name} by AI based on syllabus discipline.`,
            source: 'ai'
          };
        }
      }
    }
  } catch (err) {
    console.warn('[EdTechAId] AI cluster detection endpoint error, using competitive rule-based classification:', err);
  }
  return null;
}

function detectModuleAcademicCluster(comp) {
  if (!comp) return SIT_ACADEMIC_CLUSTERS.ENG;

  // 1. Explicit AI-identified or instructor-selected cluster passed in comp or profile
  const existingCluster = comp.academicCluster || (comp.useProfileCluster !== false ? currentModuleProfile?.academicCluster : null);
  if (existingCluster && existingCluster.code && SIT_ACADEMIC_CLUSTERS[existingCluster.code.toUpperCase()]) {
    const c = SIT_ACADEMIC_CLUSTERS[existingCluster.code.toUpperCase()];
    return { ...c, source: existingCluster.source || 'ai', rationale: existingCluster.rationale || '' };
  }

  // 2. Competitive Multi-Cluster Scoring Engine
  const code = (comp.moduleCode || '').trim().toUpperCase();
  const name = (comp.moduleName || '').trim().toLowerCase();
  const desc = (comp.moduleDescriptor || comp.moduleDescription || '').trim().toLowerCase();
  const outcomesText = (comp.learningOutcomes || []).map(o => (typeof o === 'string' ? o : o.text || '')).join(' ').toLowerCase();
  const activitiesText = (comp.learningActivities || []).map(a => (typeof a === 'string' ? a : a.details ? `${a.activity} ${a.details}` : a.activity || '')).join(' ').toLowerCase();
  const topicsText = (comp.topicsCovered || []).map(t => (typeof t === 'string' ? t : t.details ? `${t.topic} ${t.details}` : t.topic || '')).join(' ').toLowerCase();

  const fullText = `${code} ${name} ${desc} ${outcomesText} ${activitiesText} ${topicsText}`;

  const scores = { ENG: 0, ICT: 0, BCD: 0, FCB: 0, HSS: 0 };

  // A. Exact Code Prefix Match (+120 points)
  if (/^(ICT|CSC|SWE|DSA|INF|CS|IS|SEC|NET|IT)\d/i.test(code)) scores.ICT += 120;
  if (/^(ENG|ME|ECE|MAE|CIV|AER|ROB|MT|SYS|EE|MLE|ENV|MME)\d/i.test(code)) scores.ENG += 120;
  if (/^(BCD|BUS|ACC|MKT|FIN|DES|COM|UXD|DCIM|HOSP|BA|ECN|HRM)\d/i.test(code)) scores.BCD += 120;
  if (/^(FCB|CHE|PHAR|FST|BIO|CHM|FSE|BME|FS|PHE|CBE)\d/i.test(code)) scores.FCB += 120;
  if (/^(HSS|OT|PT|NUR|RAD|DIET|SLT|HSC|DR|RT|PHT|OCT)\d/i.test(code)) scores.HSS += 120;

  // B. High-Precision Title Keywords (+40 points)
  if (/\b(software|computer science|programming|coding|python|javascript|data science|cybersecurity|cloud|machine learning|artificial intelligence|web development|algorithms|information security)\b/i.test(name)) scores.ICT += 40;
  if (/\b(engineering|mechanical|electrical|mechatronics|robotics|aerospace|civil|cad|mechanics|thermodynamics|circuit|structural)\b/i.test(name)) scores.ENG += 40;
  if (/\b(business|accountancy|accounting|marketing|finance|hospitality|communication|design-thinking|ux design|user experience|media)\b/i.test(name)) scores.BCD += 40;
  if (/\b(pharmaceutical|food science|food technology|biotechnology|chemical engineering|bioprocess|chemistry|fermentation|biochemistry)\b/i.test(name)) scores.FCB += 40;
  if (/\b(occupational therapy|physiotherapy|nursing|clinical|patient care|rehabilitation|allied health|diagnostic radiography|radiation therapy|dietetics|speech therapy)\b/i.test(name)) scores.HSS += 40;

  // C. Full Text Domain Pattern Scoring (+15 points per match)
  const countMatches = (regex) => (fullText.match(regex) || []).length;

  scores.ICT += countMatches(/\b(software engineering|programming|coding|python|javascript|java|c\+\+|cybersecurity|machine learning|artificial intelligence|cloud computing|database|sql|devops|git|algorithms|data structures|neural network|front-end|back-end|api)\b/gi) * 15;
  scores.ENG += countMatches(/\b(mechanical|electrical|mechatronics|robotics|aerospace|civil engineering|thermodynamics|cad|solidworks|finite element|circuit design|mechanics of materials|structural analysis|fluid mechanics|kinematics|microcontroller)\b/gi) * 15;
  scores.BCD += countMatches(/\b(accountancy|financial accounting|marketing strategy|business administration|finance|hospitality management|design-thinking|corporate communication|ux design|user experience|digital media|journalism|brand management|supply chain)\b/gi) * 15;
  scores.FCB += countMatches(/\b(pharmaceutical engineering|food science|food technology|biotechnology|chemical engineering|bioprocess engineering|cleanroom|chemistry laboratory|fermentation|biochemistry|good manufacturing practice|gmp|chromatography)\b/gi) * 15;
  scores.HSS += countMatches(/\b(occupational therapy|physiotherapy|nursing care|clinical reasoning|patient assessment|allied health|diagnostic radiography|radiation therapy|rehabilitation therapy|dietetics|speech-language pathology|gait analysis|therapeutic intervention)\b/gi) * 15;

  let bestCluster = 'ENG';
  let maxScore = -1;
  Object.keys(scores).forEach(c => {
    if (scores[c] > maxScore) {
      maxScore = scores[c];
      bestCluster = c;
    }
  });

  // Default if no score: check heuristics
  if (maxScore <= 0) {
    if (/\b(computer|data|software|web|code|cyber)\b/i.test(fullText)) bestCluster = 'ICT';
    else if (/\b(business|finance|market|account)\b/i.test(fullText)) bestCluster = 'BCD';
    else if (/\b(food|chem|bio|pharma)\b/i.test(fullText)) bestCluster = 'FCB';
    else if (/\b(patient|therapy|nurse|clinical)\b/i.test(fullText)) bestCluster = 'HSS';
    else bestCluster = 'ENG';
  }

  return { ...SIT_ACADEMIC_CLUSTERS[bestCluster], source: 'rule' };
}

function onAcademicClusterChanged() {
  const select = $('out-academic-cluster');
  if (!select) return;
  const newCode = select.value;
  if (SIT_ACADEMIC_CLUSTERS[newCode]) {
    const info = { ...SIT_ACADEMIC_CLUSTERS[newCode], source: 'user', rationale: 'Manually customized by instructor' };
    if (currentModuleProfile) {
      currentModuleProfile.academicCluster = info;
    }
    const badgeText = $('out-cluster-ai-badge-text');
    if (badgeText) badgeText.textContent = 'Instructor Selected';
    const rationale = $('out-cluster-rationale');
    if (rationale) rationale.textContent = 'Manually customized by instructor.';

    const comp = getModuleProfileComponents();
    comp.academicCluster = info;
    generateAndRenderPrincipledRecommendations(comp, false);
    showToast(`🎓 Cluster updated to ${info.name}! Recommendations refreshed.`);
  }
}

