// Helper: Safely retrieve documented SIT repository evidence for any tool
function getToolDocumentedEvidence(tool) {
  if (!tool) return null;
  const numId = Number(tool.id);
  if (numId && SIT_REPOSITORY_DOCUMENTED_EVIDENCE[numId]) {
    return SIT_REPOSITORY_DOCUMENTED_EVIDENCE[numId];
  }
  const nameLower = (tool.name || '').toLowerCase().replace(/\s*\(sit\)/gi, '').trim();
  for (const id in SIT_REPOSITORY_DOCUMENTED_EVIDENCE) {
    const candidate = (typeof SIT_EDTECH_TOOLS !== 'undefined' ? SIT_EDTECH_TOOLS : []).find(t => t.id === Number(id));
    if (candidate) {
      const candLower = candidate.name.toLowerCase().replace(/\s*\(sit\)/gi, '').trim();
      if (nameLower === candLower || nameLower.includes(candLower) || candLower.includes(nameLower)) {
        return SIT_REPOSITORY_DOCUMENTED_EVIDENCE[id];
      }
    }
  }
  return null;
}

