// Helper: safe word boundary match
function textContainsAnyTrigger(fullText, triggers) {
  if (!fullText || !triggers || triggers.length === 0) return false;
  return triggers.some(trig => {
    const t = trig.toLowerCase();
    return fullText.includes(t) || (typeof hasWord === 'function' && hasWord(fullText, t));
  });
}

// Tool Bloom profile mapper
function getToolBloomsProfile(tool) {
  const name = (tool.name || '').toLowerCase();
  const desc = (tool.description || '').toLowerCase();
  const cat = (tool.category || '').toLowerCase();

  if (name.includes('slido') || name.includes('classpoint') || name.includes('wooclap') || name.includes('mentimeter')) {
    return { level: "Remember & Understand (Level 1-2)", levelRank: 2, verbs: ['understand', 'recall', 'identify', 'explain', 'describe'] };
  }
  if (name.includes('gradescope') || name.includes('timelygrader') || name.includes('feedbackaid')) {
    return { level: "Evaluate & Assess (Level 5)", levelRank: 5, verbs: ['evaluate', 'assess', 'critique', 'grade', 'solve', 'apply'] };
  }
  if (name.includes('teamaid') || name.includes('padlet') || name.includes('convolo') || name.includes('miro') || name.includes('thinking gym')) {
    return { level: "Apply & Analyze (Level 3-4)", levelRank: 4, verbs: ['apply', 'analyze', 'create', 'design', 'collaborate', 'synthesize'] };
  }
  if (name.includes('classaid') || name.includes('ai buddy') || name.includes('lumi') || name.includes('noodle factory') || name.includes('walter')) {
    return { level: "Analyze & Evaluate (Level 4-5)", levelRank: 5, verbs: ['analyze', 'evaluate', 'apply', 'diagnose', 'examine', 'solve'] };
  }
  if (name.includes('h5p') || name.includes('articulate') || name.includes('camtasia') || name.includes('descript')) {
    return { level: "Understand & Apply (Level 2-3)", levelRank: 3, verbs: ['understand', 'apply', 'explain', 'demonstrate'] };
  }
  if (name.includes('ai-orate') || name.includes('vsm') || name.includes('nudgyt') || name.includes('edoc') || name.includes('grow pro')) {
    return { level: "Evaluate & Create (Level 5-6)", levelRank: 6, verbs: ['evaluate', 'create', 'defend', 'justify', 'practice', 'demonstrate', 'apply'] };
  }
  if (name.includes('assessmentaid')) {
    return { level: "Create & Evaluate (Level 5-6)", levelRank: 6, verbs: ['create', 'design', 'evaluate', 'assess', 'develop'] };
  }
  return { level: "Apply & Understand (Level 2-3)", levelRank: 3, verbs: ['apply', 'understand', 'demonstrate', 'practice'] };
}

