let aiIntentInputTimer = null;

function onAiIntentInputDebounced(text) {
  if (aiIntentInputTimer) clearTimeout(aiIntentInputTimer);
  aiIntentInputTimer = setTimeout(() => {
    autoSelectIntentsFromText(text, false);
  }, 350);
}

function triggerAiIntentAutoMatch() {
  const input = $('ai-intent-input-text');
  if (!input) return;
  const text = input.value.trim();
  if (!text) {
    input.focus();
    showToast('💡 Please type or paste your intended uses (or click a sample prompt below)!');
    return;
  }
  autoSelectIntentsFromText(text, true);
}

function applySampleIntentText(sampleText) {
  const input = $('ai-intent-input-text');
  if (input) {
    input.value = sampleText;
  }
  autoSelectIntentsFromText(sampleText, true);
}

