function getToolIconHelper(tool) {
  if (!tool) return '🛠️';
  if (tool.name.includes('Gradescope')) return '📝';
  if (tool.name.includes('FeedbackFruits')) return '🍇';
  if (tool.name.includes('Slido')) return '📊';
  if (tool.name.includes('Mentimeter')) return '💡';
  if (tool.name.includes('Miro')) return '🤝';
  if (tool.name.includes('Padlet')) return '📌';
  if (tool.name.includes('Lumi')) return '🤖';
  if (tool.name.includes('ClassAId')) return '🎓';
  if (tool.name.includes('Noodle Factory')) return '🍜';
  if (tool.name.includes('Nudgyt')) return '🎭';
  if (tool.name.includes('AI-ORATE')) return '🗣️';
  if (tool.name.includes('LAMS')) return '👥';
  if (tool.name.includes('Turnitin')) return '🔍';
  if (tool.name.includes('Camtasia') || tool.name.includes('Panopto')) return '🎥';
  if (tool.name.includes('Articulate') || tool.name.includes('H5P')) return '🎨';
  if (tool.name.includes('Kialo')) return '⚖️';
  if (tool.name.includes('TeamAId')) return '👥';
  if (tool.name.includes('ClassPoint')) return '🪄';
  if (tool.name.includes('Wooclap')) return '⚡';
  if (tool.isAi) return '🤖';
  return '🛠️';
}

