  const primaryIntent = matchedIntents[0] || (selectedIntents[0] || 'your teaching goals');
  const intentsAnalysis = analyzePedagogicalIntents(matchedIntents.length > 0 ? matchedIntents : selectedIntents);

  // 1. AI-Powered Dynamic Generation for SIT Central Platforms & Catalog Tools
