function filterRecCategory(cat, btn) {
  currentRecCategory = cat;

  const buttons = document.querySelectorAll('.decision-pill-btn, .rec-filter-btn');
  buttons.forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');

  const cards = document.querySelectorAll('.tool-card');
  cards.forEach(card => {
    const cardCat = card.getAttribute('data-category');
    if (cat === 'all' || cardCat === cat) {
      card.style.display = 'flex';
    } else {
      card.style.display = 'none';
    }
  });
}

function copyPromptCard(promptId, btn) {
  const el = $(promptId);
  if (!el) return;
  const text = el.textContent;

  navigator.clipboard.writeText(text).then(() => {
    const origText = btn.textContent;
    btn.textContent = '✓ Copied!';
    showToast('📋 Prompt template copied to clipboard!');
    setTimeout(() => btn.textContent = origText, 2000);
  });
}

function copyRecommendationsReport() {
  const text = buildRecommendationsReportText();
  navigator.clipboard.writeText(text).then(() => {
    showToast('📋 Full Multi-Agent Recommendations Report copied!');
  });
}

function downloadRecommendationsReport() {
  const text = buildRecommendationsReportText();
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const code = $('out-module-code')?.textContent?.trim() || 'MODULE';
  a.href = url;
  a.download = `AI_Recommendations_${code}.txt`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast(`⬇️ Downloaded report as AI_Recommendations_${code}.txt`);
}

function buildRecommendationsReportText() {
  const code = $('out-module-code')?.textContent?.trim() || 'ENG1010';
  const name = $('out-module-name')?.textContent?.trim() || 'Engineering Graphics';
  const outcomes = getListItems('list-outcomes');
  const topics = getListItems('list-topics');

  const tools = getCuratedToolsForModule(code, name, true, outcomes, {});

  return [
    `=============================================================`,
    `EDTECH AI - PEDAGOGICAL & AI TOOL RECOMMENDATIONS REPORT`,
    `=============================================================`,
    `Module: ${code} - ${name}`,
    `Generated on: ${new Date().toLocaleString()}`,
    `Framework: SAMR Model (Augmentation & Redefinition) • Bloom's Taxonomy`,
    ``,
    `-------------------------------------------------------------`,
    `1. TARGET LEARNING OUTCOMES TO ENHANCE`,
    `-------------------------------------------------------------`,
    outcomes.map((lo, i) => `${i + 1}. ${lo}`).join('\n') || 'All standard module learning outcomes.',
    ``,
    `-------------------------------------------------------------`,
    `2. RECOMMENDED AI TOOLS & IMPLEMENTATION STRATEGY`,
    `-------------------------------------------------------------`,
    tools.map((t, i) => [
      `[${i + 1}] ${t.name} (${t.categoryLabel}) - ${t.access}`,
      `    Target: ${t.loMapping}`,
      `    Overview: ${t.description}`,
      `    Implementation: ${t.implementation}`,
      ``
    ].join('\n')).join('\n'),
    `-------------------------------------------------------------`,
    `3. INSTRUCTIONAL WORKFLOW TIMELINE`,
    `-------------------------------------------------------------`,
    `• Pre-Class Priming: Spatial reasoning simulators & diagnostic concept quizzes.`,
    `• In-Class Studio: Live CAD AI co-pilot for real-time constraint error troubleshooting.`,
    `• Post-Class Review: Vision-based automated rubric feedback on 2D drafting submissions.`,
    ``,
    `-------------------------------------------------------------`,
    `4. SAMPLE INSTRUCTOR PROMPTS`,
    `-------------------------------------------------------------`,
    `PROMPT 1: Dynamic Drawing Problem Generator`,
    `"You are an expert Engineering Graphics instructor. Create 3 progressive technical drawing problem specifications for ISO Tolerances and Fits with mechanical scenarios, nominal dimensions, and common student drafting mistakes."`,
    ``,
    `PROMPT 2: CAD Constraint Socratic Tutor`,
    `"Act as a Socratic SolidWorks teaching assistant. Guide a student with an over-defined assembly error by asking 2 diagnostic questions on degrees of freedom rather than giving direct answers."`,
    `=============================================================`
  ].join('\n');
}

