function extractMentionedToolsFromQuery(query) {
  if (!query || typeof query !== 'string') return [];
  const qLower = query.toLowerCase();
  const matched = [];

  for (const tool of SIT_EDTECH_TOOLS) {
    const fullName = (tool.name || '').toLowerCase();
    const baseName = fullName.replace(/\s*\([^)]*\)/g, '').trim();

    const candidates = [fullName, baseName];
    if (fullName.includes('noodle factory') || fullName.includes('walter')) candidates.push('noodle factory', 'walter');
    if (fullName.includes('articulate')) candidates.push('articulate 360', 'articulate');
    if (fullName.includes('ai buddy')) candidates.push('ai buddy', 'aibuddy');
    if (fullName.includes('examena')) candidates.push('examena');
    if (fullName.includes('gradescope')) candidates.push('gradescope');
    if (fullName.includes('feedbackfruits')) candidates.push('feedbackfruits', 'feedbackfruit');
    if (fullName.includes('timelygrader')) candidates.push('timelygrader');
    if (fullName.includes('classpoint')) candidates.push('classpoint');
    if (fullName.includes('slido')) candidates.push('slido');
    if (fullName.includes('padlet')) candidates.push('padlet');
    if (fullName.includes('h5p')) candidates.push('h5p');
    if (fullName.includes('descript')) candidates.push('descript');
    if (fullName.includes('camtasia')) candidates.push('camtasia');
    if (fullName.includes('mentimeter')) candidates.push('mentimeter');
    if (fullName.includes('wooclap')) candidates.push('wooclap');
    if (fullName.includes('miro')) candidates.push('miro');
    if (fullName.includes('classaid')) candidates.push('classaid');
    if (fullName.includes('lumi tutor') || fullName.includes('lumi')) candidates.push('lumi tutor', 'lumi');
    if (fullName.includes('ai-orate')) candidates.push('ai-orate', 'ai orate', 'orate');
    if (fullName.includes('nudgyt')) candidates.push('nudgyt');
    if (fullName.includes('teamaid')) candidates.push('teamaid', 'team-aid');
    if (fullName.includes('forumaid')) candidates.push('forumaid', 'forum-aid');
    if (fullName.includes('feedbackaid')) candidates.push('feedbackaid', 'feedback-aid');
    if (fullName.includes('assessmentaid')) candidates.push('assessmentaid', 'assessment-aid');
    if (fullName.includes('convolo')) candidates.push('convolo');
    if (fullName.includes('thinking gym')) candidates.push('thinking gym');
    if (fullName.includes('grow pro')) candidates.push('grow pro', 'growpro');
    if (fullName.includes('edoc')) candidates.push('edoc');
    if (fullName.includes('vsm')) candidates.push('vsm');
    if (fullName.includes('lams')) candidates.push('lams');

    const isMatch = candidates.some(cand => {
      if (!cand || cand.length < 2) return false;
      const escaped = cand.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(`(^|[^a-z0-9])${escaped}([^a-z0-9]|$)`, 'i');
      return regex.test(qLower);
    });

    if (isMatch && !matched.some(m => m.id === tool.id)) {
      matched.push(tool);
    }
  }

  return matched;
}

function getToolBloomsTaxonomy(tool) {
  const name = (tool.name || '').toLowerCase();
  const cat = (tool.category || '').toLowerCase();
  if (name.includes('slido') || name.includes('classpoint') || name.includes('wooclap') || name.includes('mentimeter')) {
    return { level: "Remember & Understand (Augmentation)", desc: "Real-time concept checks, retrieval practice, and active lecture polling with immediate comprehension feedback." };
  }
  if (name.includes('gradescope') || name.includes('timelygrader') || name.includes('assessmentaid')) {
    return { level: "Evaluate (Modification)", desc: "Streamlines rubric evaluation, automated question-by-question grading, and actionable competency feedback." };
  }
  if (name.includes('teamaid') || name.includes('padlet') || name.includes('convolo') || name.includes('miro') || name.includes('thinking gym')) {
    return { level: "Apply & Analyze (Modification)", desc: "Collaborative design critique, peer analysis, brainstorming, and transparent team accountability." };
  }
  if (name.includes('classaid') || name.includes('ai buddy') || name.includes('lumi') || name.includes('noodle factory') || name.includes('walter')) {
    return { level: "Analyze & Evaluate (Redefinition)", desc: "24/7 Socratic inquiry, clinical reasoning practice, and adaptive tutoring without revealing direct answers." };
  }
  if (name.includes('h5p') || name.includes('articulate') || name.includes('camtasia') || name.includes('descript')) {
    return { level: "Understand & Apply (Augmentation)", desc: "Interactive multimedia scenarios, branching video decision-trees, and self-paced knowledge checks." };
  }
  if (name.includes('ai-orate') || name.includes('vsm') || name.includes('nudgyt') || name.includes('edoc') || name.includes('grow pro')) {
    return { level: "Evaluate & Create (Redefinition)", desc: "Authentic professional simulations, oral viva exam evaluations, and immersive workplace practice." };
  }
  return { level: "Apply & Understand", desc: "Digital support for module deliverables and continuous learning checkpoints." };
}

function getToolSetupReadiness(tool) {
  const name = (tool.name || '').toLowerCase();
  if (name.includes('slido') || name.includes('padlet') || name.includes('wooclap') || name.includes('mentimeter') || name.includes('miro')) {
    return { tier: "🟢 Plug & Play (Zero Setup)", time: "1–3 mins", student: "Students join instantly via QR code or web link without mandatory account creation." };
  }
  if (name.includes('gradescope') || name.includes('classpoint') || name.includes('feedbackfruits') || name.includes('feedbackaid') || name.includes('h5p')) {
    return { tier: "🟡 Light Setup (10–15 mins)", time: "10–15 mins", student: "Students access via SIT Single Sign-On (SSO) and direct xSiTe LMS external tool links." };
  }
  return { tier: "🔵 Guided Pilot (STLA Support)", time: "Pilot Scope (1–2 days)", student: "STLA EdTech team provides sandbox provisioning, course roster sync, and instructor onboarding." };
}

function generateDetailedComparisonAnswerHTML(toolsList, context) {
  if (!toolsList || toolsList.length === 0) {
    toolsList = [SIT_EDTECH_TOOLS[0], SIT_EDTECH_TOOLS[1]].filter(Boolean);
  }
  if (toolsList.length === 1) {
    const second = SIT_EDTECH_TOOLS.find(t => t.id !== toolsList[0].id) || SIT_EDTECH_TOOLS[1];
    if (second) toolsList.push(second);
  }

  const tableHTML = (toolsList.length >= 3)
    ? buildMultiToolComparisonTableHTML(toolsList, context)
    : buildToolComparisonTableHTML(toolsList[0], toolsList[1], context, {
        recWinnerName: toolsList[0]?.name,
        verdictReason: `Comparing <strong>${escapeHtml(toolsList[0]?.name || '')}</strong> and <strong>${escapeHtml(toolsList[1]?.name || '')}</strong>: Both tools provide distinct pedagogical advantages for your syllabus deliverables.`
      });

  const topPick = toolsList[0] || SIT_EDTECH_TOOLS[0];
  const secondaryTools = toolsList.slice(1);

  const narrativeHTML = `
    <div style="margin-top: 16px; font-size: 12px; color: #1e293b; line-height: 1.55;">
      <h4 style="margin: 0 0 10px 0; font-size: 13.5px; color: #0f172a; display: flex; align-items: center; gap: 6px;">
        <span>🎯</span> <strong>Detailed Pedagogical Breakdown (${toolsList.length} Tools):</strong>
      </h4>

      <!-- 1. Pedagogical Strengths & Bloom's Alignment -->
      <div style="background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 10px; padding: 12px 14px; margin-bottom: 10px;">
        <strong style="color: #0f172a; font-size: 12.5px;">1️⃣ Pedagogical Strengths &amp; Bloom's Taxonomy Alignment:</strong>
        <ul style="margin: 6px 0 0 0; padding-left: 18px; line-height: 1.5; color: #334155; font-size: 11.5px;">
          ${toolsList.map(t => {
            const b = getToolBloomsTaxonomy(t);
            return `<li style="margin-bottom: 6px;"><strong>${t?.icon || '🛠️'} ${escapeHtml(t?.name || 'Tool')}:</strong> <span style="background: #f1f5f9; color: #1e293b; font-weight: 700; padding: 1px 6px; border-radius: 6px; font-size: 10.5px;">Bloom's: ${b.level}</span> — ${escapeHtml(b.desc)}</li>`;
          }).join('')}
        </ul>
      </div>

      <!-- 2. Setup Effort & Student Learning Curve -->
      <div style="background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 10px; padding: 12px 14px; margin-bottom: 10px;">
        <strong style="color: #0f172a; font-size: 12.5px;">2️⃣ Setup Effort &amp; Student Learning Curve:</strong>
        <ul style="margin: 6px 0 0 0; padding-left: 18px; line-height: 1.5; color: #334155; font-size: 11.5px;">
          ${toolsList.map(t => {
            const r = getToolSetupReadiness(t);
            return `<li style="margin-bottom: 6px;"><strong>${t?.icon || '🛠️'} ${escapeHtml(t?.name || 'Tool')}:</strong> <span style="font-weight: 700; color: #1e3a8a;">${r.tier}</span> (${r.time}) — ${escapeHtml(r.student)}</li>`;
          }).join('')}
        </ul>
      </div>

      <!-- 3. Best Use Cases for SIT Modules -->
      <div style="background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 10px; padding: 12px 14px; margin-bottom: 10px;">
        <strong style="color: #0f172a; font-size: 12.5px;">3️⃣ Best Use Cases for SIT Modules:</strong>
        <ul style="margin: 6px 0 0 0; padding-left: 18px; line-height: 1.5; color: #334155; font-size: 11.5px;">
          ${toolsList.map(t => {
            const useCase = (t?.useCasesSIT && t.useCasesSIT[0]) || (t?.useCasesGeneral && t.useCasesGeneral[0]) || t?.description || 'Active class participation';
            return `<li style="margin-bottom: 6px;"><strong>${t?.icon || '🛠️'} ${escapeHtml(t?.name || 'Tool')}:</strong> ${escapeHtml(useCase)}</li>`;
          }).join('')}
        </ul>
      </div>

      <!-- 4. Consultant Recommendation: Which Tool to Start With -->
      <div style="background: #f0fdf4; border: 1.5px solid #86efac; border-radius: 10px; padding: 12px 14px;">
        <strong style="color: #166534; font-size: 12.5px;">4️⃣ Consultant Recommendation: Which Tool to Start With:</strong>
        <p style="margin: 6px 0 6px 0; color: #14532d; font-size: 11.5px; line-height: 1.5;">
          🏆 <strong>Primary Recommendation:</strong> We advise starting with <strong>${escapeHtml(topPick?.name || 'SIT Recommended Tool')}</strong> as your initial pedagogical anchor. It provides the fastest route to student impact with manageable instructor preparation.
        </p>
        <p style="margin: 0; color: #166534; font-size: 11px; line-height: 1.5;">
          🔄 <strong>Implementation Roadmap:</strong> Once students are comfortable with <strong>${escapeHtml(topPick?.name || 'the primary tool')}</strong>, layer in <strong>${escapeHtml(secondaryTools.map(t => t?.name || '').filter(Boolean).join(' and ') || 'complementary tools')}</strong> during later assignment, laboratory, or project phases to build a cohesive blended learning ecosystem.
        </p>
      </div>
    </div>
  `;

  return tableHTML + narrativeHTML;
}

// ──────────────────────────────────────────────────────────
//  AI MATCHMAKER CONSULTANT EXPLANATION & ACTIVITY GENERATORS
// ──────────────────────────────────────────────────────────
function generateRecommendationExplanationHTML(targetTool, context, query) {
  if (!targetTool) targetTool = SIT_EDTECH_TOOLS[0];
  const toolName = targetTool.name;
  const instructor = context?.instructor || {};
  const code = context?.code || 'your module';
  const name = context?.name || '';
  const selectedIntents = instructor.intents || [];

  // 1. Instructor Need / Intended Use
  let statedNeed = '';
  if (selectedIntents && selectedIntents.length > 0) {
    statedNeed = selectedIntents.join(', ');
  } else if (targetTool.category) {
    statedNeed = targetTool.category;
  } else {
    statedNeed = 'Active learning, student engagement, and structured coursework support';
  }

  // 2. Tool Capability
  const capabilities = (targetTool.capabilities || targetTool.features || targetTool.useCasesGeneral || []).slice(0, 3);
  const capText = capabilities.length > 0 
    ? capabilities.map(c => `<code>${escapeHtml(c)}</code>`).join('; ')
    : escapeHtml(targetTool.description);

  // 3. Match Rationale
  let matchRationale = '';
  const tNameLower = toolName.toLowerCase();
  if (tNameLower.includes('ai buddy')) {
    matchRationale = `AI Buddy directly targets <strong>Socratic questioning and clinical/reasoning evaluation</strong> without revealing direct answers. Instead of a generic conversational chatbot, it guides students through reflective inquiry, assesses student responses against established discipline frameworks, and performs gap analysis to identify where students struggle with theory or bias. This makes it the strongest match for university cohorts requiring structured cognitive and clinical reasoning practice.`;
  } else if (tNameLower.includes('slido')) {
    matchRationale = `Slido provides near-zero friction live polling, word clouds, and anonymous crowd-upvoted Q&amp;A. It is the top recommendation when instructors need instant comprehension pulse checks and an anonymous channel for quieter students to raise questions during lectures without requiring account creation.`;
  } else if (tNameLower.includes('classpoint')) {
    matchRationale = `ClassPoint integrates directly into Microsoft PowerPoint, allowing you to transform static lecture slides into interactive quizzes, word clouds, and gamified leaderboards without leaving your presentation interface.`;
  } else if (tNameLower.includes('gradescope')) {
    matchRationale = `Gradescope provides AI answer grouping, dynamic rubrics, and automated code grading. It drastically reduces grading turnaround for large cohorts and delivers consistent, criterion-mapped feedback.`;
  } else if (tNameLower.includes('feedbackaid')) {
    matchRationale = `FeedbackAId specializes in mass personalized feedback for reflective writing and open-ended coursework, linking directly to xSiTe assignment Dropbox submissions.`;
  } else if (tNameLower.includes('padlet')) {
    matchRationale = `Padlet provides an intuitive multimedia gallery board where students can post thoughts, externalize design ideas, and review peer contributions with zero learning curve.`;
  } else if (tNameLower.includes('classaid')) {
    matchRationale = `ClassAId allows instructors to build custom RAG-powered course AI agents grounded strictly in your syllabus materials, providing 24/7 student tutoring and assignment FAQ answers.`;
  } else if (tNameLower.includes('ai-orate')) {
    matchRationale = `AI-ORATE evaluates applied communication and professional competencies through interactive oral and chat-based scenario tasks with AI-assisted rubric grading and xSiTe LMS integration.`;
  } else {
    matchRationale = `<strong>${escapeHtml(toolName)}</strong> offers direct alignment with your module's pedagogical delivery through ${escapeHtml((targetTool.useCasesGeneral && targetTool.useCasesGeneral[0]) || targetTool.description)}. It ranked highest because its verified features fulfill your stated learning outcomes with minimal student friction and full SIT institutional support.`;
  }

  // 4. Practical Classroom Example
  let classroomExample = '';
  if (tNameLower.includes('ai buddy')) {
    classroomExample = `In your weekly classes or lab prep, assign a case scenario to students. Students interact with <strong>AI Buddy</strong> to gather initial details and structure their analysis (e.g. using clinical frameworks). AI Buddy prompts them with Socratic follow-up questions when they miss critical diagnostic steps. You can review the cohort analytics dashboard to spot common conceptual gaps before starting the in-class debrief.`;
  } else if (tNameLower.includes('slido')) {
    classroomExample = `At the 15-minute mark of your lecture, display a Slido QR code on your slide. Run a 1-minute pulse check with a multiple-choice question on the core formula. Meanwhile, keep an open anonymous Q&amp;A session where students upvote confusing concepts, allowing you to address top-voted student questions during the final 10 minutes.`;
  } else if (tNameLower.includes('classpoint')) {
    classroomExample = `While presenting your slide deck, trigger an interactive Drawing or Word Cloud question. Students join from their mobile devices via a PIN code and submit their annotated diagrams directly to your PowerPoint screen in real time.`;
  } else if (tNameLower.includes('gradescope')) {
    classroomExample = `After an assignment submission deadline, upload paper scripts or code files. Gradescope's AI groups identical answers together, allowing you to grade 80 similar submissions in a single click while updating rubric point deductions dynamically across the entire cohort.`;
  } else if (tNameLower.includes('feedbackaid')) {
    classroomExample = `Students submit their midterm draft reflection into the xSiTe Dropbox. FeedbackAId analyzes the submissions against your specified competency rubrics, generating individualized formative feedback on analytical depth and critical thinking before final submission.`;
  } else {
    const sitCase = (targetTool.useCasesSIT && targetTool.useCasesSIT[0]) || (targetTool.useCasesGeneral && targetTool.useCasesGeneral[0]) || 'Active classroom participation and assessment';
    classroomExample = `Deploy <strong>${escapeHtml(toolName)}</strong> during your weekly sessions: ${escapeHtml(sitCase)}. Students engage directly via browser or xSiTe link, reinforcing their understanding through hands-on practice.`;
  }

  // 5. Recommended Next Steps
  const contact = (targetTool.supportContacts && targetTool.supportContacts[0]) || (targetTool.accessInfo && targetTool.accessInfo[0]) || 'STLA EdTech Team (edtech@singaporetech.edu.sg)';
  const nextStep1 = (targetTool.nextSteps && targetTool.nextSteps[0]) || 'Reach out to the EdTech team to discuss scope';

  return `
    <div style="background: #ffffff; border: 1.5px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 12px; line-height: 1.6; font-size: 12px; color: #1e293b;">
      <div style="display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; margin-bottom: 12px; flex-wrap: wrap; gap: 8px;">
        <strong style="font-size: 14px; color: #0f172a; display: flex; align-items: center; gap: 6px;">
          <span>🎯</span> Recommendation Rationale: ${escapeHtml(toolName)}
        </strong>
        <span style="background: #ecfdf5; color: #047857; font-weight: 700; font-size: 11px; padding: 2px 10px; border-radius: 12px;">Top Ranked Match</span>
      </div>

      <div style="margin-bottom: 14px;">
        <h4 style="margin: 0 0 6px 0; color: #0f172a; font-size: 13px; font-weight: 700;">📌 Why it was recommended</h4>
        <ul style="margin: 0; padding-left: 18px; color: #334155; line-height: 1.6;">
          <li style="margin-bottom: 6px;">
            <strong>Instructor Need:</strong> ${escapeHtml(statedNeed)}
          </li>
          <li style="margin-bottom: 6px;">
            <strong>Relevant Tool Capability:</strong> ${capText}
          </li>
          <li>
            <strong>The Match:</strong> ${matchRationale}
          </li>
        </ul>
      </div>

      <div style="background: #f8fafc; border-left: 3px solid #3b82f6; padding: 10px 14px; border-radius: 0 8px 8px 0; margin-bottom: 14px;">
        <h4 style="margin: 0 0 4px 0; color: #1e40af; font-size: 12.5px; font-weight: 700;">🏫 How it fits your class</h4>
        <p style="margin: 0; color: #334155; font-size: 11.5px; line-height: 1.55;">
          ${classroomExample}
        </p>
      </div>

      <div style="background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 8px; padding: 10px 14px;">
        <h4 style="margin: 0 0 6px 0; color: #166534; font-size: 12.5px; font-weight: 700;">🚀 Recommended Next Steps</h4>
        <ol style="margin: 0; padding-left: 18px; color: #15803d; font-size: 11.5px; line-height: 1.55;">
          <li>Identify the specific learning activity or assessment topic in <strong>${escapeHtml(code)}</strong>.</li>
          <li>Set up or request access: <em>${escapeHtml(contact)}</em> (${escapeHtml(nextStep1)}).</li>
          <li>Configure the activity or case prompts based on your syllabus requirements.</li>
          <li>Test it with a small student pilot group or tutorial section.</li>
          <li>Review student engagement and progress analytics to refine before full trimester rollout.</li>
        </ol>
      </div>
    </div>
  `;
}

